# ===== bot/adapters/obs_v1.py (spliced) =====
"""Canonical observation schema — version ``obs_v1`` (P2.1).

This module is the **frozen boundary** on the observation side of the pipeline:

    QueryMovePlayer --[Featurizer]--> CanonicalObs (obs_v1) --> PolicyCore

It defines *only* the schema — the exact tensor shapes, the per-tensor field
layout, the normalization convention, and the padding/mask convention. The
logic that fills these tensors lives in ``bot.featurizer`` (P2.2), the single
module both the trainer and the shipped bot import so they can never disagree.

Full field-by-field documentation is in ``notes/canonical-spec.md``; the tables
there and the constants here are kept in lock-step by ``tests/test_featurizer``.

**Normalization convention (one rule).** Every spatial quantity — relative
positions, radii, frame-diff velocities, wall distances — is expressed in units
of the *half vision window* ``half = vision_size / 2`` for the current frame.
Because ``vision_size`` grows sub-linearly with the player's own size
(``get_player_vision_size``), this makes the whole observation egocentric **and**
scale-adaptive: as the agent grows, the world zooms out with it and the same
tactical geometry maps to the same numbers. The one absolute-scale cue the agent
would otherwise lose is re-injected as ``self_vec[0]`` (``vision_size`` itself).

All arrays are ``float32``. Padding rows are all-zero and flagged by a companion
mask (``1.0`` real, ``0.0`` padding). Outputs are clipped to the bounds below so
every value is finite and range-bounded regardless of input (property-tested).
"""


from dataclasses import dataclass

import numpy as np


# --- version tag ------------------------------------------------------------

#: Bumped (obs_v2, …) whenever the tensor layout below changes. Recorded in the
#: model registry alongside every checkpoint so an old policy is always paired
#: with the adapter it was trained against.
OBS_VERSION = "obs_v1"

# --- tensor shapes ----------------------------------------------------------

#: Self / global feature vector width (see ``notes/canonical-spec.md`` §self).
SELF_DIM = 16

#: Nearest-K food pellets. 160 exist (``spec.FOOD_COUNT``); we keep the 64
#: closest. Fields: (dx, dy, dist).
FOOD_MAX = 64
FOOD_DIM = 3

#: Nearest-K *enemy* blobs (own blobs never appear here — ``visible_blobs`` is
#: enemies only). Up to 7×16 = 112 can exist; we keep the 32 closest.
#: Fields: (dx, dy, radius, vel_x, vel_y, merge_cooldown, can_eat_me,
#: split_threat, i_can_eat).
ENEMY_MAX = 32
ENEMY_DIM = 9

#: Own blobs, from ``you.blobs`` (never K-truncated — at most MAX_BLOB_COUNT).
#: Fields: (dx, dy, radius, merge_cooldown, can_split).
OWN_MAX = spec.MAX_BLOB_COUNT  # 16
OWN_DIM = 5

#: Nearest-K viruses. 6 exist (``spec.VIRUS_COUNT``); slot for 8.
#: Fields: (dx, dy, dist, radius, is_dangerous).
VIRUS_MAX = 8
VIRUS_DIM = 5

# --- clipping bounds (guarantee finite, range-bounded outputs) --------------
# These are generous — for genuinely in-vision entities the normalized values
# sit within roughly [-1, 1]; the clips only ever bind on pathological inputs
# (e.g. an own blob flung far outside the window) so NaN/inf can never escape.

POS_CLIP = 8.0   # relative positions, distances, wall distances (half-units)
VEL_CLIP = 4.0   # frame-diff velocities (half-units / frame)
RAD_CLIP = 8.0   # radii (half-units)


@dataclass(frozen=True)
class CanonicalObs:
    """One featurized frame, in the canonical layout above.

    ``*_mask`` arrays are ``1.0`` for a real entity and ``0.0`` for padding, so a
    deep-set encoder can masked-pool without seeing padding. ``is_reset`` is
    ``True`` on the first frame of an episode-segment for this seat — the game's
    very first query, or the first query after a respawn gap (dead players are
    not queried, so the round number jumps). The caller resets the GRU hidden
    state whenever it sees ``is_reset`` (recorded design decision, P2.2), and on
    that frame all velocity estimates are zero (no previous frame to diff).
    """

    self_vec: np.ndarray      # (SELF_DIM,)
    food: np.ndarray          # (FOOD_MAX, FOOD_DIM)
    food_mask: np.ndarray     # (FOOD_MAX,)
    enemy: np.ndarray         # (ENEMY_MAX, ENEMY_DIM)
    enemy_mask: np.ndarray    # (ENEMY_MAX,)
    own: np.ndarray           # (OWN_MAX, OWN_DIM)
    own_mask: np.ndarray      # (OWN_MAX,)
    virus: np.ndarray         # (VIRUS_MAX, VIRUS_DIM)
    virus_mask: np.ndarray    # (VIRUS_MAX,)
    is_reset: bool

    def validate(self) -> None:
        """Assert exact shapes, dtypes, finiteness and mask bounds.

        Cheap enough to call in tests and in a debug build; not on the hot path.
        """
        checks = [
            ("self_vec", self.self_vec, (SELF_DIM,)),
            ("food", self.food, (FOOD_MAX, FOOD_DIM)),
            ("food_mask", self.food_mask, (FOOD_MAX,)),
            ("enemy", self.enemy, (ENEMY_MAX, ENEMY_DIM)),
            ("enemy_mask", self.enemy_mask, (ENEMY_MAX,)),
            ("own", self.own, (OWN_MAX, OWN_DIM)),
            ("own_mask", self.own_mask, (OWN_MAX,)),
            ("virus", self.virus, (VIRUS_MAX, VIRUS_DIM)),
            ("virus_mask", self.virus_mask, (VIRUS_MAX,)),
        ]
        for name, arr, shape in checks:
            assert arr.shape == shape, f"{name}: shape {arr.shape} != {shape}"
            assert arr.dtype == np.float32, f"{name}: dtype {arr.dtype} != float32"
            assert np.all(np.isfinite(arr)), f"{name}: non-finite value"
        for name, mask in (
            ("food_mask", self.food_mask),
            ("enemy_mask", self.enemy_mask),
            ("own_mask", self.own_mask),
            ("virus_mask", self.virus_mask),
        ):
            assert np.all((mask == 0.0) | (mask == 1.0)), f"{name}: non-binary mask"


__all__ = [
    "OBS_VERSION",
    "SELF_DIM",
    "FOOD_MAX",
    "FOOD_DIM",
    "ENEMY_MAX",
    "ENEMY_DIM",
    "OWN_MAX",
    "OWN_DIM",
    "VIRUS_MAX",
    "VIRUS_DIM",
    "POS_CLIP",
    "VEL_CLIP",
    "RAD_CLIP",
    "CanonicalObs",
]


# ===== bot/adapters/act_v1.py (spliced) =====
"""Canonical action schema — version ``act_v1`` (P2.1).

The **frozen boundary** on the action side of the pipeline:

    PolicyCore --> CanonicalAction (act_v1) --[ActionAdapter]--> MovePlayer

The policy emits a discrete heading bin plus a split bit; the adapter turns that
into the engine's ``MovePlayer`` (a unit ``DirectionModel`` vector + split bool).

This file freezes the *interface* (the bin count, the canonical action struct,
the bin→vector geometry). The exhaustive validity-fuzz proof that no emitted
move can ever trip ``MoveValidator`` is P2.3; the geometry it certifies lives
here so P2.1 downstream (the policy head width = ``HEADING_BINS``) is pinned now.

Only ``lib`` is imported (match-legal surface); never ``engine`` or ``train``.
"""


import math
from dataclasses import dataclass

from lib.interface.events.moves.move_player import MovePlayer
from lib.models.penguin_model import DirectionModel

#: Bumped (act_v2, …) if the action surface changes (more bins, an eject action,
#: continuous heading, …). Recorded per checkpoint in the registry.
ACT_VERSION = "act_v1"

#: Number of discrete heading bins the policy chooses among. Evenly spaced on the
#: full circle starting at +x (bin 0 → 0°/east), counter-clockwise. 24 bins ⇒
#: 15° resolution, plenty for a heading-controlled agent and cheap to argmax.
HEADING_BINS = 24

#: Precomputed unit vectors, one per bin (bin i at angle ``2π·i/HEADING_BINS``).
#: Kept as a plain tuple so the hot path does no trig and no allocation.
_BIN_VECTORS: tuple[tuple[float, float], ...] = tuple(
    (math.cos(2.0 * math.pi * i / HEADING_BINS), math.sin(2.0 * math.pi * i / HEADING_BINS))
    for i in range(HEADING_BINS)
)


def bin_to_vector(heading_bin: int) -> tuple[float, float]:
    """Unit ``(x, y)`` heading for a bin index (``0 <= heading_bin < HEADING_BINS``)."""
    return _BIN_VECTORS[heading_bin]


def _argmax(values) -> int:
    """Index of the largest element (lowest index on ties — deterministic).

    Works on any indexable sequence (Python list, tuple, or ``np.ndarray``) so
    the adapter never forces a NumPy dependency and both the torch trainer and
    the NumPy bot can call it.
    """
    best_i = 0
    best_v = values[0]
    for i in range(1, len(values)):
        v = values[i]
        if v > best_v:
            best_v = v
            best_i = i
    return best_i


def decode_logits(heading_logits, split_logit, split_threshold: float = 0.0) -> "CanonicalAction":
    """Greedy decode of a policy's raw outputs into a :class:`CanonicalAction`.

    ``heading_logits`` is a length-``HEADING_BINS`` sequence (argmax → bin);
    ``split_logit`` is a scalar (split iff ``> split_threshold``; the default 0.0
    treats it as a pre-sigmoid logit). Kept sampling-free: the shipped bot acts
    greedily (P5.2), and the trainer samples upstream and passes the chosen
    ``CanonicalAction`` directly.
    """
    if len(heading_logits) != HEADING_BINS:
        raise ValueError(
            f"expected {HEADING_BINS} heading logits, got {len(heading_logits)}"
        )
    return CanonicalAction(
        heading_bin=_argmax(heading_logits),
        split=bool(float(split_logit) > split_threshold),
    )


@dataclass(frozen=True)
class CanonicalAction:
    """What the policy commits to each turn: a heading bin and whether to split.

    Deliberately backend-agnostic — the trainer produces one of these from its
    torch heads, the shipped bot produces one from the NumPy forward pass, and
    both hand it to the *same* ``ActionAdapter`` so training and match time emit
    identical wire moves.
    """

    heading_bin: int
    split: bool

    def __post_init__(self) -> None:
        if not (0 <= self.heading_bin < HEADING_BINS):
            raise ValueError(
                f"heading_bin {self.heading_bin} out of range [0, {HEADING_BINS})"
            )


class ActionAdapter:
    """Canonical action → engine ``MovePlayer``. Stateless; safe to share."""

    version = ACT_VERSION
    heading_bins = HEADING_BINS

    @staticmethod
    def to_move(player_id: int, action: CanonicalAction) -> MovePlayer:
        """Build the validated ``MovePlayer`` for ``player_id`` from ``action``.

        The heading is always a non-zero unit vector (a bin always maps to a point
        on the unit circle), so ``DirectionModel``'s "exactly one representation,
        both x and y present" validator is satisfied by construction — this is the
        property P2.3 fuzzes exhaustively.

        The ``_BIN_VECTORS`` table is a compile-time constant of ``cos``/``sin``
        values, so ``(x, y)`` is inherently finite; the explicit ``isfinite``
        guard is belt-and-suspenders for engine v2026.1.10's
        ``FiniteBaseModel(allow_inf_nan=False)`` — it converts any future
        non-finite heading (e.g. a continuous-heading act_v2) into a clear
        adapter-boundary error instead of a pydantic ``ValidationError`` raised
        deep in wire serialization mid-match.
        """
        x, y = _BIN_VECTORS[action.heading_bin]
        x, y = float(x), float(y)
        if not (math.isfinite(x) and math.isfinite(y)):
            raise ValueError(
                f"non-finite heading ({x}, {y}) for bin {action.heading_bin}; "
                "a MovePlayer with NaN/Inf is rejected by the engine "
                "(allow_inf_nan=False)"
            )
        return MovePlayer(
            player_id=int(player_id),
            direction=DirectionModel(x=x, y=y),
            split=bool(action.split),
        )

    @staticmethod
    def logits_to_move(
        player_id: int, heading_logits, split_logit, split_threshold: float = 0.0
    ) -> MovePlayer:
        """Decode raw policy outputs straight to a ``MovePlayer`` (the bot's hot
        path): ``decode_logits`` then :meth:`to_move`."""
        return ActionAdapter.to_move(
            player_id, decode_logits(heading_logits, split_logit, split_threshold)
        )


__all__ = [
    "ACT_VERSION",
    "HEADING_BINS",
    "bin_to_vector",
    "decode_logits",
    "CanonicalAction",
    "ActionAdapter",
]

obs_v1 = act_v1 = _sys.modules[__name__]

# ===== bot/featurizer.py (spliced) =====
"""The featurizer (P2.2) — the *one* observation module.

Both the trainer and the shipped bot import ``Featurizer`` from here, so the
features a policy is trained on are, by construction, byte-identical to the
features it acts on at match time. This kills the trainer/inference-disagreement
bug class outright.

What it does, per query (all rules verified against the engine — see
``notes/mechanics-spec.md``):

* **Egocentric + vision-normalized.** Everything is measured relative to
  ``view_center`` (the vision-window center) and divided by the half vision
  window ``half = vision_size / 2`` (``bot.adapters.obs_v1`` normalization rule).
  Note ``view_center`` is the mass centroid **clamped** to keep the window on-map
  (engine v2026.1.10), so it equals ``you.pos`` except near a wall, where the
  own-blob offset it induces usefully encodes wall proximity; centering on the
  viewport (not ``you.pos``) keeps every *visible* entity within ``[-1, 1]``.
* **K-nearest entity selection** with a **deterministic** tie-break: entities are
  ordered by ``(distance, id)`` where ``id`` is the id the engine assigns in the
  query (``food_id`` / ``virus_id`` / ``(player_id, blob_id)``). As of engine
  **v2026.1.14** these are **per-frame public ordinals** (the "leaked info" fix —
  ``get_public_visible_*`` re-indexes them ``0, 1, 2…`` each query rather than
  exposing the engine's stable internal ids), but they remain **unique within a
  frame**, so the order is still a pure function of the *set* of visible entities
  and invariant to the order the engine listed them in.
* **Frame-difference velocity estimation** for enemy blobs. Enemies' split eject
  momentum (``eject_vx/vy``) is *hidden* from observations, so a recently-split
  enemy carries large invisible velocity that only a frame diff can recover —
  this is **mandatory**. Because v2026.1.14 re-indexes ``blob_id`` per frame, a
  blob **cannot** be matched across frames by id; the :class:`EntityTracker`
  instead matches each enemy blob to the nearest same-player blob in the previous
  frame within one tick's plausible travel (``_VEL_MATCH_RADIUS``), greedily and
  deterministically. A blob with no such predecessor (new, just-split, or
  re-entered vision) correctly gets zero velocity.
* **Relational, verified-mechanics features** — never raw ids:
  ``merge_cooldown`` (exposed for enemies too: >0 ⇒ just-split, can't re-merge);
  ``can_eat_me`` / ``i_can_eat`` using the *exact* rule (**mass** ratio
  ``EAT_SIZE_RATIO`` as of engine v2026.1.12 **and** center-coverage);
  ``split_threat`` computed against
  the enemy's **split reach** (``radius + SPLIT_REACH`` ≈ +8.9 units), not its
  body radius; per-blob ``can_split`` (mass ≥ ``SPLIT_MIN_MASS``); virus
  ``is_dangerous`` (any own blob mass > ``VIRUS_POP_MASS_THRESHOLD`` ⇒ contact
  shatters it).

**Reset semantics.** Dead players are never queried, so on respawn the round
number jumps. The featurizer detects that gap (and the very first frame), clears
the tracker, zeros all velocities that frame, and flags ``is_reset`` so the
caller resets the GRU hidden state (recorded design decision). One
:class:`Featurizer` instance serves one seat; parallel games use one each.
"""


import math
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np



def _clip(value: float, bound: float) -> float:
    """Scalar clip to ``[-bound, bound]`` (own tiny helper — no NumPy per value)."""
    if value > bound:
        return bound
    if value < -bound:
        return -bound
    return value


#: Max plausible single-tick blob displacement, used to gate cross-frame velocity
#: matching (v2026.1.14: ids are per-frame ordinals, so we match by position). A
#: blob moves at most ``movement_speed(radius) ≤ BASE_PLAYER_SPEED`` per tick, plus
#: up to ``SPLIT_EJECT_SPEED`` of residual eject momentum right after a split. Any
#: candidate previous blob farther than this cannot be the same physical blob, so
#: we leave the current blob's velocity at zero rather than fabricate a match.
_VEL_MATCH_RADIUS = spec.BASE_PLAYER_SPEED + spec.SPLIT_EJECT_SPEED
_VEL_MATCH_R2 = _VEL_MATCH_RADIUS * _VEL_MATCH_RADIUS


class EntityTracker:
    """Holds the previous frame's visible enemy-blob positions **grouped by
    player**, for frame-difference velocity estimation.

    Since engine v2026.1.14 re-indexes ``blob_id`` per frame (per-target public
    ordinals), a blob can no longer be matched across frames by id. We instead
    keep each player's visible-blob positions and let :meth:`Featurizer` match
    each current blob to the nearest same-player blob from the previous frame.
    Only blobs visible in the *previous* frame can yield a velocity; a blob that
    was out of vision (new, or re-entered) gets zero velocity — we genuinely
    could not observe its motion while it was gone. Cleared on our death/respawn
    (the :class:`Featurizer` calls :meth:`clear` on a round gap).
    """

    __slots__ = ("_by_player",)

    def __init__(self) -> None:
        # player_id -> list of (x, y) for that player's blobs visible last frame.
        self._by_player: Dict[int, List[Tuple[float, float]]] = {}

    def clear(self) -> None:
        self._by_player.clear()

    def prev_positions(self, player_id: int) -> Optional[List[Tuple[float, float]]]:
        return self._by_player.get(player_id)

    def commit(self, by_player: Dict[int, List[Tuple[float, float]]]) -> None:
        """Replace the tracked set with exactly this frame's visible enemy blobs.

        Replacing (rather than updating) is deliberate: a blob absent this frame
        is dropped, so if it reappears later it correctly starts from zero
        velocity instead of diffing across the invisible gap.
        """
        self._by_player = by_player


class Featurizer:
    """Turns a ``QueryMovePlayer`` into a :class:`~bot.adapters.obs_v1.CanonicalObs`.

    Stateful across a single seat's episode (holds the velocity tracker and the
    last round number for respawn-gap detection). Call :meth:`reset` to force a
    fresh episode; otherwise resets happen automatically on a round-number gap.
    """

    obs_version = obs_v1.OBS_VERSION

    def __init__(self) -> None:
        self.tracker = EntityTracker()
        self._last_round: Optional[int] = None

    def reset(self) -> None:
        """Forget all cross-frame state (velocity tracker + round watermark)."""
        self.tracker.clear()
        self._last_round = None

    # -- main entry point ---------------------------------------------------

    def featurize(self, query) -> CanonicalObs:
        """Featurize one alive-player query into the canonical layout."""
        is_reset = self._last_round is None or query.round != self._last_round + 1
        if is_reset:
            self.tracker.clear()

        cx, cy = query.view_center
        half = query.vision_size / 2.0
        inv_half = 1.0 / half if half > 0.0 else 0.0

        own_blobs = query.you.blobs
        own_stats = self._own_stats(own_blobs)
        own_max_r = own_stats["max_r"]

        self_vec = self._self_vector(query, cx, cy, inv_half, own_stats)
        own, own_mask = self._own_tensor(own_blobs, cx, cy, inv_half)
        food, food_mask = self._food_tensor(query.visible_food, cx, cy, inv_half)
        virus, virus_mask = self._virus_tensor(
            query.visible_viruses, cx, cy, inv_half, own_stats["max_mass"]
        )
        enemy, enemy_mask = self._enemy_tensor(
            query.visible_blobs, cx, cy, inv_half, own_max_r, is_reset
        )

        self._last_round = query.round
        return CanonicalObs(
            self_vec=self_vec,
            food=food,
            food_mask=food_mask,
            enemy=enemy,
            enemy_mask=enemy_mask,
            own=own,
            own_mask=own_mask,
            virus=virus,
            virus_mask=virus_mask,
            is_reset=is_reset,
        )

    # -- self / global vector ----------------------------------------------

    @staticmethod
    def _own_stats(own_blobs: Sequence) -> dict:
        radii = [b.radius for b in own_blobs]
        masses = [r * r for r in radii]
        cds = [b.merge_cooldown for b in own_blobs]
        # An alive player always has ≥1 blob (dead ⇒ never queried), but guard
        # anyway so the featurizer can never divide by an empty sequence.
        if not radii:
            return {
                "n": 0, "max_r": 0.0, "min_r": 0.0, "max_mass": 0.0,
                "min_cd": 0, "max_cd": 0, "can_split": 0.0, "can_pop": 0.0,
                "player_radius": 0.0,
            }
        max_mass = max(masses)
        return {
            "n": len(radii),
            "max_r": max(radii),
            "min_r": min(radii),
            "max_mass": max_mass,
            "min_cd": min(cds),
            "max_cd": max(cds),
            "can_split": 1.0 if max_mass >= spec.SPLIT_MIN_MASS else 0.0,
            "can_pop": 1.0 if max_mass > spec.VIRUS_POP_MASS_THRESHOLD else 0.0,
            "player_radius": math.sqrt(sum(masses)),
        }

    def _self_vector(self, query, cx, cy, inv_half, s: dict) -> np.ndarray:
        cd_norm = 1.0 / spec.SPLIT_COOLDOWN_FRAMES
        vec = np.zeros(SELF_DIM, dtype=np.float32)
        vec[0] = query.vision_size / spec.VISION_SIZE - 1.0  # absolute-scale cue (≥0)
        vec[1] = s["n"] / spec.MAX_BLOB_COUNT
        vec[2] = _clip(s["player_radius"] * inv_half, RAD_CLIP)
        vec[3] = _clip(s["max_r"] * inv_half, RAD_CLIP)
        vec[4] = _clip(s["min_r"] * inv_half, RAD_CLIP)
        vec[5] = s["min_cd"] * cd_norm
        vec[6] = s["max_cd"] * cd_norm
        vec[7] = s["can_split"]
        vec[8] = s["can_pop"]
        vec[9] = _clip(cx * inv_half, POS_CLIP)                       # dist to left wall
        vec[10] = _clip((spec.ARENA_SIZE - cx) * inv_half, POS_CLIP)  # to right wall
        vec[11] = _clip(cy * inv_half, POS_CLIP)                      # to bottom wall
        vec[12] = _clip((spec.ARENA_SIZE - cy) * inv_half, POS_CLIP)  # to top wall
        vec[13] = query.round / spec.MAX_ROUNDS
        vec[14] = min(len(query.visible_blobs), ENEMY_MAX) / ENEMY_MAX
        vec[15] = min(len(query.visible_food), FOOD_MAX) / FOOD_MAX
        return vec

    # -- own blobs ----------------------------------------------------------

    def _own_tensor(self, own_blobs, cx, cy, inv_half):
        arr = np.zeros((OWN_MAX, OWN_DIM), dtype=np.float32)
        mask = np.zeros(OWN_MAX, dtype=np.float32)
        cd_norm = 1.0 / spec.SPLIT_COOLDOWN_FRAMES
        # Own blobs are canonically ordered by blob_id (the engine's own
        # sorted_blobs order); never more than MAX_BLOB_COUNT of them.
        blobs = sorted(own_blobs, key=lambda b: b.blob_id)[:OWN_MAX]
        for i, b in enumerate(blobs):
            bx, by = b.pos
            mass = b.radius * b.radius
            arr[i, 0] = _clip((bx - cx) * inv_half, POS_CLIP)
            arr[i, 1] = _clip((by - cy) * inv_half, POS_CLIP)
            arr[i, 2] = _clip(b.radius * inv_half, RAD_CLIP)
            arr[i, 3] = b.merge_cooldown * cd_norm
            arr[i, 4] = 1.0 if mass >= spec.SPLIT_MIN_MASS else 0.0
            mask[i] = 1.0
        return arr, mask

    # -- food ---------------------------------------------------------------

    def _food_tensor(self, visible_food, cx, cy, inv_half):
        arr = np.zeros((FOOD_MAX, FOOD_DIM), dtype=np.float32)
        mask = np.zeros(FOOD_MAX, dtype=np.float32)
        # (distance², id, dx, dy) — squared distance keeps the K-nearest sort
        # exact and cheap; id (food_id) breaks ties deterministically.
        scored: List[Tuple[float, int, float, float]] = []
        for f in visible_food:
            fx, fy = f.pos
            dx, dy = fx - cx, fy - cy
            scored.append((dx * dx + dy * dy, f.food_id, dx, dy))
        scored.sort()
        for i, (d2, _fid, dx, dy) in enumerate(scored[:FOOD_MAX]):
            arr[i, 0] = _clip(dx * inv_half, POS_CLIP)
            arr[i, 1] = _clip(dy * inv_half, POS_CLIP)
            arr[i, 2] = _clip(math.sqrt(d2) * inv_half, POS_CLIP)
            mask[i] = 1.0
        return arr, mask

    # -- viruses ------------------------------------------------------------

    def _virus_tensor(self, visible_viruses, cx, cy, inv_half, own_max_mass):
        arr = np.zeros((VIRUS_MAX, VIRUS_DIM), dtype=np.float32)
        mask = np.zeros(VIRUS_MAX, dtype=np.float32)
        # A virus is dangerous to *me* iff contact would shatter one of my blobs,
        # i.e. any own blob has mass > the pop threshold (mass > 2.7 as of v2026.1.11).
        dangerous = 1.0 if own_max_mass > spec.VIRUS_POP_MASS_THRESHOLD else 0.0
        scored: List[Tuple[float, int, float, float, float]] = []
        for v in visible_viruses:
            vx, vy = v.pos
            dx, dy = vx - cx, vy - cy
            scored.append((dx * dx + dy * dy, v.virus_id, dx, dy, v.radius))
        scored.sort()
        for i, (d2, _vid, dx, dy, r) in enumerate(scored[:VIRUS_MAX]):
            arr[i, 0] = _clip(dx * inv_half, POS_CLIP)
            arr[i, 1] = _clip(dy * inv_half, POS_CLIP)
            arr[i, 2] = _clip(math.sqrt(d2) * inv_half, POS_CLIP)
            arr[i, 3] = _clip(r * inv_half, RAD_CLIP)
            arr[i, 4] = dangerous
            mask[i] = 1.0
        return arr, mask

    # -- enemy blobs --------------------------------------------------------

    def _estimate_velocities(
        self, visible_blobs, is_reset
    ) -> Dict[Tuple[int, int], Tuple[float, float]]:
        """Per-frame velocities keyed by this frame's ``(player_id, blob_id)``.

        v2026.1.14 makes ``blob_id`` a per-frame ordinal, so we match by position:
        for each player, greedily pair current blobs with the previous frame's
        blobs of the same player, nearest-first, each previous blob used once, and
        only within ``_VEL_MATCH_RADIUS``. Pairs are ordered by
        ``(distance², current blob_id, previous index)`` — a deterministic key
        that does not depend on the order the engine listed the blobs, so the
        result is permutation-invariant. Unmatched current blobs (new / just-split
        / re-entered vision) are simply absent from the map ⇒ zero velocity.
        """
        vel: Dict[Tuple[int, int], Tuple[float, float]] = {}
        if is_reset:
            return vel

        # Group this frame's blobs by player: player_id -> [(blob_id, x, y)].
        cur_by_player: Dict[int, List[Tuple[int, float, float]]] = {}
        for b in visible_blobs:
            cur_by_player.setdefault(b.player_id, []).append((b.blob_id, b.pos[0], b.pos[1]))

        for pid, cur in cur_by_player.items():
            prev = self.tracker.prev_positions(pid)
            if not prev:
                continue
            pairs: List[Tuple[float, int, int]] = []
            for bid, bx, by in cur:
                for pi, (px, py) in enumerate(prev):
                    d2 = (bx - px) * (bx - px) + (by - py) * (by - py)
                    if d2 <= _VEL_MATCH_R2:
                        pairs.append((d2, bid, pi))
            pairs.sort()
            # index current blobs by blob_id for lookup during greedy assignment
            cur_by_id = {bid: (bx, by) for bid, bx, by in cur}
            used_cur: set = set()
            used_prev: set = set()
            for d2, bid, pi in pairs:
                if bid in used_cur or pi in used_prev:
                    continue
                used_cur.add(bid)
                used_prev.add(pi)
                bx, by = cur_by_id[bid]
                px, py = prev[pi]
                vel[(pid, bid)] = (bx - px, by - py)
        return vel

    def _enemy_tensor(self, visible_blobs, cx, cy, inv_half, own_max_r, is_reset):
        arr = np.zeros((ENEMY_MAX, ENEMY_DIM), dtype=np.float32)
        mask = np.zeros(ENEMY_MAX, dtype=np.float32)
        cd_norm = 1.0 / spec.SPLIT_COOLDOWN_FRAMES
        eat_ratio = spec.EAT_SIZE_RATIO
        split_reach = spec.SPLIT_REACH
        own_mass = own_max_r * own_max_r

        # Position-based cross-frame velocity match (ids are per-frame ordinals).
        vel = self._estimate_velocities(visible_blobs, is_reset)

        # Score every visible enemy blob; keep the K nearest by (distance, id).
        scored: List[Tuple[float, Tuple[int, int], object, float, float]] = []
        new_positions: Dict[int, List[Tuple[float, float]]] = {}
        for b in visible_blobs:
            bx, by = b.pos
            dx, dy = bx - cx, by - cy
            key = (b.player_id, b.blob_id)
            new_positions.setdefault(b.player_id, []).append((bx, by))
            scored.append((dx * dx + dy * dy, key, b, dx, dy))
        scored.sort(key=lambda t: (t[0], t[1]))

        for i, (d2, key, b, dx, dy) in enumerate(scored[:ENEMY_MAX]):
            dist = math.sqrt(d2)
            bx, by = b.pos
            er = b.radius
            em = er * er

            # frame-diff velocity (zero on reset frames / first sighting / no match)
            vx, vy = vel.get(key, (0.0, 0.0))

            # exact verified eat rules (MASS ratio AND center-coverage) — engine
            # v2026.1.12 made _can_eat_blob a mass ratio: eater.mass ≥ ratio·target.mass
            # (⇔ radius ratio √ratio). Center-coverage (target center within eater
            # disc) is unchanged: dist ≤ eater.radius.
            can_eat_me = 1.0 if (em >= eat_ratio * own_mass and dist <= er) else 0.0
            i_can_eat = 1.0 if (own_mass >= eat_ratio * em and dist <= own_max_r) else 0.0

            # split-reach threat: enemy can split (mass ≥ 2), a resulting half
            # (mass em/2) could still eat me by mass ratio, and I sit within its reach.
            split_threat = 0.0
            if em >= spec.SPLIT_MIN_MASS and (em * 0.5) >= eat_ratio * own_mass:
                gap = dist - er
                if gap <= split_reach:
                    split_threat = 1.0 - max(0.0, gap) / split_reach

            arr[i, 0] = _clip(dx * inv_half, POS_CLIP)
            arr[i, 1] = _clip(dy * inv_half, POS_CLIP)
            arr[i, 2] = _clip(er * inv_half, RAD_CLIP)
            arr[i, 3] = _clip(vx * inv_half, VEL_CLIP)
            arr[i, 4] = _clip(vy * inv_half, VEL_CLIP)
            arr[i, 5] = b.merge_cooldown * cd_norm
            arr[i, 6] = can_eat_me
            arr[i, 7] = split_threat
            arr[i, 8] = i_can_eat
            mask[i] = 1.0

        # Record this frame's positions for next frame's velocity diff.
        self.tracker.commit(new_positions)
        return arr, mask


__all__ = ["Featurizer", "EntityTracker"]


# ===== bot/inference.py (spliced) =====
"""P5.2 — pure-NumPy inference: the match-time forward pass.

Hand-rolled mirror of the :class:`~train.model.AgarPolicy` **actor path** —
per-category deep-set encoders (shared 2-layer MLP → masked mean+max pool),
trunk, one ``GRUCell`` step, heading/split heads — consuming the featurizer's
:class:`~bot.adapters.obs_v1.CanonicalObs` directly. No torch, no ``train``
imports (this file ships in the bundle; the import-linter contract enforces
the boundary). Weights come from ``train/export.py``'s ``weights.npz``.

Numerical contract (P5.3): logits agree with the torch actor within float32
accumulation-order tolerance (~1e-5 abs); the *chosen action* is identical
except on documented near-ties. Bit-exactness is neither expected nor required.

The GRU step matches ``torch.nn.GRUCell`` exactly::

    r  = σ(x·Wir^T + bir + h·Whr^T + bhr)
    z  = σ(x·Wiz^T + biz + h·Whz^T + bhz)
    n  = tanh(x·Win^T + bin + r ⊙ (h·Whn^T + bhn))
    h' = (1 − z) ⊙ n + z ⊙ h

with ``weight_ih``/``weight_hh`` stacked ``[r; z; n]`` along dim 0.

Hidden-state policy: :meth:`NumpyPolicy.step` zeroes the incoming hidden when
``obs.is_reset`` is set — the same contract as training, and the featurizer
raises ``is_reset`` on the game's first frame and after every respawn gap, so
the caller just threads ``hidden`` through.
"""


import json
from typing import Any, Dict, Mapping, Tuple

import numpy as np


#: Mirrors ``train.export.MANIFEST_KEY`` (no train import allowed here).
MANIFEST_KEY = "__manifest__"


def _sigmoid(x: np.ndarray) -> np.ndarray:
    return 1.0 / (1.0 + np.exp(-x))


class _Encoder:
    """One deep-set encoder: shared 2-layer MLP → masked mean+max pool."""

    __slots__ = ("w1", "b1", "w2", "b2")

    def __init__(self, arrays: Mapping[str, np.ndarray], prefix: str) -> None:
        # Pre-transpose once so the per-turn path is plain (K,D)@(D,H) matmuls.
        self.w1 = np.ascontiguousarray(arrays[f"{prefix}.mlp.0.weight"].T)
        self.b1 = arrays[f"{prefix}.mlp.0.bias"]
        self.w2 = np.ascontiguousarray(arrays[f"{prefix}.mlp.2.weight"].T)
        self.b2 = arrays[f"{prefix}.mlp.2.bias"]

    def __call__(self, x: np.ndarray, mask: np.ndarray) -> np.ndarray:
        h = np.maximum(x @ self.w1 + self.b1, 0.0)
        h = np.maximum(h @ self.w2 + self.b2, 0.0)          # (K, H)
        count = mask.sum()
        if count == 0.0:                                     # all padding
            return np.zeros(2 * h.shape[1], dtype=np.float32)
        m = mask[:, None]
        mean = (h * m).sum(axis=0) / count
        mx = np.where(m == 0.0, np.float32(np.finfo(np.float32).min), h).max(axis=0)
        return np.concatenate([mean, mx])


class NumpyPolicy:
    """The deployed policy: ``weights.npz`` in, one ``step`` per turn."""

    def __init__(self, arrays: Mapping[str, np.ndarray],
                 manifest: Mapping[str, Any]) -> None:
        if manifest.get("obs_version") != OBS_VERSION or \
                manifest.get("act_version") != ACT_VERSION or \
                int(manifest.get("heading_bins", 0)) != HEADING_BINS:
            raise ValueError(f"weights manifest {manifest} does not match this bot's "
                             f"adapters ({OBS_VERSION}/{ACT_VERSION}/{HEADING_BINS})")
        self.manifest = dict(manifest)
        self.hidden_size = int(manifest["hidden_size"])

        self.food_enc = _Encoder(arrays, "food_enc")
        self.enemy_enc = _Encoder(arrays, "enemy_enc")
        self.own_enc = _Encoder(arrays, "own_enc")
        self.virus_enc = _Encoder(arrays, "virus_enc")

        self.trunk_w = np.ascontiguousarray(arrays["trunk.0.weight"].T)
        self.trunk_b = arrays["trunk.0.bias"]

        H = self.hidden_size
        w_ih, w_hh = arrays["gru.weight_ih"], arrays["gru.weight_hh"]
        b_ih, b_hh = arrays["gru.bias_ih"], arrays["gru.bias_hh"]
        # Split the stacked [r; z; n] gates once at load.
        self.wir, self.wiz, self.win = (np.ascontiguousarray(w_ih[i * H:(i + 1) * H].T)
                                        for i in range(3))
        self.whr, self.whz, self.whn = (np.ascontiguousarray(w_hh[i * H:(i + 1) * H].T)
                                        for i in range(3))
        self.bir, self.biz, self.bin_ = (b_ih[i * H:(i + 1) * H] for i in range(3))
        self.bhr, self.bhz, self.bhn = (b_hh[i * H:(i + 1) * H] for i in range(3))

        self.head_w = np.ascontiguousarray(arrays["heading_head.weight"].T)
        self.head_b = arrays["heading_head.bias"]
        self.split_w = np.ascontiguousarray(arrays["split_head.weight"].T)
        self.split_b = arrays["split_head.bias"]

    # -- loading --------------------------------------------------------------

    @classmethod
    def load(cls, path) -> "NumpyPolicy":
        """Load from an ``.npz`` path *or* a file-like object (``np.load``
        accepts both — the single-file submission build feeds a BytesIO of
        embedded weight bytes)."""
        with np.load(path) as z:
            manifest: Dict[str, Any] = json.loads(bytes(z[MANIFEST_KEY]).decode())
            arrays = {k: np.ascontiguousarray(z[k], dtype=np.float32)
                      for k in z.files if k != MANIFEST_KEY}
        return cls(arrays, manifest)

    def initial_hidden(self) -> np.ndarray:
        return np.zeros(self.hidden_size, dtype=np.float32)

    # -- the per-turn hot path -------------------------------------------------

    def step(self, obs: CanonicalObs,
             hidden: np.ndarray) -> Tuple[np.ndarray, float, np.ndarray]:
        """One forward step → ``(heading_logits(24,), split_logit, new_hidden)``.

        Zeroes the incoming ``hidden`` when ``obs.is_reset`` (same contract as
        the torch model — first frame of a game / first frame after respawn).
        """
        if obs.is_reset:
            hidden = np.zeros_like(hidden)

        feats = np.concatenate([
            obs.self_vec,
            self.food_enc(obs.food, obs.food_mask),
            self.enemy_enc(obs.enemy, obs.enemy_mask),
            self.own_enc(obs.own, obs.own_mask),
            self.virus_enc(obs.virus, obs.virus_mask),
        ])
        x = np.maximum(feats @ self.trunk_w + self.trunk_b, 0.0)

        r = _sigmoid(x @ self.wir + self.bir + hidden @ self.whr + self.bhr)
        z = _sigmoid(x @ self.wiz + self.biz + hidden @ self.whz + self.bhz)
        n = np.tanh(x @ self.win + self.bin_ + r * (hidden @ self.whn + self.bhn))
        new_hidden = ((1.0 - z) * n + z * hidden).astype(np.float32)

        heading_logits = new_hidden @ self.head_w + self.head_b
        split_logit = float((new_hidden @ self.split_w + self.split_b)[0])
        return heading_logits, split_logit, new_hidden

    def act(self, obs: CanonicalObs,
            hidden: np.ndarray) -> Tuple[CanonicalAction, np.ndarray]:
        """Greedy decode — exactly how the bot plays (P5.4's hot path)."""
        heading_logits, split_logit, new_hidden = self.step(obs, hidden)
        return decode_logits(heading_logits, split_logit, 0.0), new_hidden


__all__ = ["NumpyPolicy", "MANIFEST_KEY"]


